function fewestMirrorEdits(nums: number[], limit: number): number {
  const n = nums.length;
  let best = Infinity;
  for (let t = 2; t <= 2 * limit; t++) {
    let cost = 0;
    for (let i = 0; i < n / 2; i++) {
      const a = nums[i], b = nums[n - 1 - i];
      if (a + b === t) continue;
      cost += t >= Math.min(a, b) + 1 && t <= Math.max(a, b) + limit ? 1 : 2;
    }
    best = Math.min(best, cost);
  }
  return best;
}

