class Solution:
    def fewestMirrorEdits(self, nums: List[int], limit: int) -> int:
        n = len(nums)
        best = float("inf")
        for t in range(2, 2 * limit + 1):
            cost = 0
            for i in range(n // 2):
                a, b = nums[i], nums[n - 1 - i]
                if a + b == t:
                    continue
                cost += 1 if min(a, b) + 1 <= t <= max(a, b) + limit else 2
            best = min(best, cost)
        return best

