function fewestMirrorEdits(nums: number[], limit: number): number {
  const n = nums.length;
  const d = new Int32Array(2 * limit + 2);
  for (let i = 0; i < n / 2; i++) {
    const a = nums[i], b = nums[n - 1 - i];
    const lo = Math.min(a, b), hi = Math.max(a, b);
    d[2] += 2;            // start at 2 edits
    d[lo + 1] -= 1;       // one edit reaches from here
    d[a + b] -= 1;        // no edit at the current sum
    d[a + b + 1] += 1;
    d[hi + limit + 1] += 1; // beyond one edit's reach again
  }
  let best = Infinity, run = 0;
  for (let t = 2; t <= 2 * limit; t++) {
    run += d[t];
    best = Math.min(best, run);
  }
  return best;
}

